#define missionShipTable_SIZE          42
#define fieldTable                     ((unsigned char *)0x7350)  /* 7 x 20 bytes */ /* +0 type (9 rocks, 10 mines), +2 position (3 x int32), +14 radius (int32 km), +18 density */
#define fieldTable_SIZE                20

